for(let i=0;i<novelChapters.length;i++){const chapter=novelChapters[i];const chapterTitle=String(chapter.title||'').trim();const pageTitle=chapterTitle&&chapterTitle!==`Chương ${chapter.number}`?`Chương ${chapter.number}: ${chapterTitle}`:`Chương ${chapter.number}`;page(`/truyen/chuong-${chapter.number}/`,pageTitle,`Trang đọc chương ${chapter.number} của Mục Thần Ký. ${chapter.kind==='full'?'Toàn văn chương.':'Tóm lược biên soạn.'}`,novelReader(chapter,{comments:comments(),esc,chapters:novelChapters}),{type:'Article'});}page('/cong-dong/','Chốn luận đạo','Không gian trao đổi, fanpage và nhóm Facebook chính thức của cộng đồng Mục Thần Ký.',heading('Chốn luận đạo','Cùng bàn luận về phim, truyện và thế giới Mục Thần Ký.','COMMUNITY')+`<div class="wrap"><section><h2>Kết nối cộng đồng</h2><div class="community-links"><a href="https://www.facebook.com/mucthanky.official" target="_blank" rel="noopener noreferrer"><span class="play-mark"><svg class="facebook-mark" viewBox="0 0 24 24" aria-hidden="true"><path d="M14.2 21v-8h2.7l.4-3.1h-3.1V8c0-.9.3-1.6 1.6-1.6h1.7V3.6c-.3 0-1.4-.1-2.6-.1-2.6 0-4.4 1.6-4.4 4.5v1.9H7.6V13h2.9v8h3.7Z"/></svg></span><span><strong>Fanpage Mục Thần Ký</strong><small>Tin tức và bài đăng chính thức của cộng đồng</small></span><b>↗</b></a><a href="https://www.facebook.com/groups/mucthanky" target="_blank" rel="noopener noreferrer"><span class="play-mark"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="3"/><path d="M3.5 19v-1.5A4.5 4.5 0 0 1 8 13h2a4.5 4.5 0 0 1 4.5 4.5V19M16 5.5a3 3 0 0 1 0 5.8M17 13h.5a3.5 3.5 0 0 1 3.5 3.5V19"/></svg></span><span><strong>Nhóm Facebook Mục Thần Ký</strong><small>Thảo luận cùng người hâm mộ</small></span><b>↗</b></a></div></section><section><div class="support-cta"><div><span class="eyebrow">TIẾP SỨC CHO BÁCH KHOA</span><h2>Giúp Đại Khư luôn có thêm điều để khám phá</h2><p>Một lời ủng hộ tùy tâm giúp dự án tiếp tục chăm chút hồ sơ, chương truyện và không gian cộng đồng.</p></div><a class="btn primary" href="/ung-ho/">Tìm hiểu cách ủng hộ <span aria-hidden="true">↗</span></a></div></section>${comments()}</div>`);page('/ung-ho/','Ủng hộ dự án Mục Thần Ký','Đồng hành duy trì bách khoa, truyện và cộng đồng Mục Thần Ký bằng khoản ủng hộ tự nguyện.',heading('Cùng giữ Đại Khư luôn sáng đèn','Mỗi sự ủng hộ là một lời động viên để Mục Thần Ký tiếp tục được gìn giữ, tra cứu và khám phá cùng nhau.','TIẾP SỨC CHO BÁCH KHOA')+`<div class="wrap support-page"><section class="support-intro"><div class="support-intro-heading"><span class="eyebrow">MỘT THẾ GIỚI · VẠN ĐIỀU KHÁM PHÁ</span><h2>Những trang tư liệu này được làm nên từ sự yêu mến</h2></div><div class="support-intro-copy"><p>Mucthanky.com là nơi người hâm mộ có thể lần theo dấu chân Tần Mục qua phim, truyện, nhân vật và những bí mật của Đại Khư. Mỗi hồ sơ được bổ sung, mỗi trang được chăm chút đều hướng đến một trải nghiệm tra cứu dễ đọc và gần gũi hơn.</p><p>Nếu website từng giúp bạn tìm được câu trả lời, gợi lại một cảnh phim yêu thích hay đơn giản là khiến bạn muốn khám phá thêm, bạn có thể tiếp sức cho dự án bằng một khoản tùy tâm. Không có mức tối thiểu và hoàn toàn không bắt buộc.</p></div></section><section class="support-card" id="ung-ho"><div class="support-copy"><span class="eyebrow">ỦNG HỘ TỰ NGUYỆN</span><h2>Tiếp sức cho hành trình Mục Thần Ký</h2><p>Đóng góp của bạn giúp duy trì website và dành thêm thời gian mở rộng bách khoa, chăm sóc thư viện hình ảnh, chương truyện cùng các công cụ cho cộng đồng.</p><dl class="support-bank-details"><div><dt>Ngân hàng</dt><dd>MB Bank</dd></div><div><dt>Số tài khoản</dt><dd class="copy-account"><span>310292</span><button class="copy-account-button" type="button" data-copy-account="310292" aria-label="Sao chép số tài khoản" title="Sao chép số tài khoản"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h3"/></svg></button><span class="sr-only" id="copy-account-status" role="status" aria-live="polite"></span></dd></div><div><dt>Chủ tài khoản</dt><dd>Nguyen Van Thuc</dd></div></dl><p class="support-safety">Mã QR không đặt sẵn số tiền. Hãy kiểm tra tên người nhận và số tài khoản hiển thị trong ứng dụng ngân hàng trước khi xác nhận.</p></div><figure class="support-qr"><img src="/assets/donate-vietqr.svg" width="540" height="640" alt="Mã QR MB Bank, tài khoản 310292, chủ tài khoản Nguyen Van Thuc" loading="eager"><figcaption>Mở ứng dụng ngân hàng và quét mã để gửi tùy tâm.</figcaption></figure></section><section class="support-impact"><div class="section-head"><div><span class="eyebrow">SỰ ĐỒNG HÀNH CỦA BẠN</span><h2>Đóng góp nhỏ, hành trình dài hơn</h2><p>Mỗi sự tiếp sức đều đáng quý, dù nhiều hay ít.</p></div></div><div class="grid"><article class="support-impact-card"><span>01</span><h3>Duy trì tư liệu</h3><p>Góp phần giữ website và các công cụ tra cứu hoạt động ổn định.</p></article><article class="support-impact-card"><span>02</span><h3>Mở rộng bách khoa</h3><p>Tiếp thêm thời gian để hoàn thiện hồ sơ nhân vật, cảnh giới và thế giới Đại Khư.</p></article><article class="support-impact-card"><span>03</span><h3>Nuôi dưỡng cộng đồng</h3><p>Cùng xây dựng một nơi để người hâm mộ chia sẻ tình yêu với phim và truyện.</p></article></div></section><section class="supporter-registry" id="danh-sach-ghi-danh"><div class="section-head"><div><span class="eyebrow">SỔ ĐỒNG HÀNH</span><h2>Những người đã ghi danh</h2><p>Mỗi cái tên là một lời động viên để dự án tiếp tục được chăm chút.</p></div></div><div class="supporter-hall-intro"><div class="supporter-hall-copy"><span class="eyebrow">DẤU ẤN ĐỒNG HÀNH</span><h3>Mỗi cái tên là một ngọn đèn nhỏ của Đại Khư</h3><p>Sổ vinh danh dành cho những người đã gửi lời tiếp sức và chủ động ghi danh. Cảm ơn bạn đã cùng giữ những trang tư liệu này tiếp tục được mở rộng.</p><a class="btn primary" href="#ung-ho">Gửi lời tiếp sức <span aria-hidden="true">↗</span></a></div><div class="supporter-hall-stat"><span class="supporter-hall-seal" aria-hidden="true"><svg viewBox="0 0 48 48"><path d="M24 4 29 9l7-1 2 7 6 4-3 7 3 7-6 4-2 7-7-1-5 5-5-5-7 1-2-7-6-4 3-7-3-7 6-4 2-7 7 1 5-5Z"/><path d="m16 24 5 5 11-12"/></svg></span><strong id="supporter-total">0</strong><span>người đã ghi danh</span></div></div><div class="supporter-instructions"><strong>Bạn muốn ghi danh?</strong><p>Khi chuyển khoản, hãy ghi nội dung <code>Ghi Danh + tên bạn muốn hiển thị</code>. Sau khi đối chiếu giao dịch, chủ website sẽ thêm tên và ngày ghi danh vào danh sách. Chỉ tên hiển thị và ngày ghi danh được công khai; thông tin giao dịch không xuất hiện trên website.</p></div><div class="supporter-controls novel-chapter-tools"><label class="novel-search"><span class="sr-only">Tìm người ghi danh</span><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input id="supporter-search" type="search" placeholder="Tìm tên người ghi danh…" autocomplete="off"></label><label class="novel-page-size"><span>Mỗi trang</span><select id="supporter-page-size" aria-label="Số người ghi danh mỗi trang"><option value="10">10 người</option><option value="50">50 người</option><option value="100">100 người</option></select></label><div class="novel-sort sort-controls" role="group" aria-label="Sắp xếp người ghi danh theo ngày"><button type="button" class="sort-control-button is-active" data-supporter-sort="newest" aria-label="Mới nhất trước" title="Mới nhất trước" aria-pressed="true"><svg class="sort-direction-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v16m-7-6 7 7 7-7"/></svg></button><button type="button" class="sort-control-button" data-supporter-sort="oldest" aria-label="Cũ nhất trước" title="Cũ nhất trước" aria-pressed="false"><svg class="sort-direction-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20V4m7 6-7-7-7 7"/></svg></button></div><select id="supporter-sort" class="sr-only" aria-label="Thứ tự ngày ghi danh"><option value="newest">Mới nhất trước</option><option value="oldest">Cũ nhất trước</option></select></div><p class="supporter-count" id="supporter-count" aria-live="polite">Đang tải danh sách…</p><div class="supporter-list" id="supporter-list" aria-live="polite"><p>Đang tải danh sách ghi danh…</p></div><nav class="supporter-pagination" id="supporter-pagination" aria-label="Phân trang danh sách ghi danh" hidden><button class="btn small" id="supporter-prev" type="button" aria-label="Trang trước" title="Trang trước"><svg class="pagination-arrow" viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg></button><div id="supporter-page-numbers" class="supporter-page-numbers" aria-label="Số trang"></div><span id="supporter-page-state"></span><button class="btn small" id="supporter-next" type="button" aria-label="Trang sau" title="Trang sau"><svg class="pagination-arrow" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg></button></nav></section><p class="support-thanks">Cảm ơn bạn đã ghé thăm và đồng hành. Dù có thể ủng hộ hay không, sự hiện diện và chia sẻ của bạn cũng đã giúp thế giới này đến gần hơn với những người yêu Mục Thần Ký.</p></div>`);page('/tai-khoan/','Tài khoản','Quản lý tài khoản Google và các hồ sơ Mục Thần Ký đã lưu của bạn.',heading('Tài khoản của bạn','Đăng nhập để đồng bộ hồ sơ đã lưu và tiếp tục khám phá thế giới Mục Thần Ký trên mọi thiết bị.','TÀI KHOẢN')+`<div class="wrap account-page" id="account-page"><p class="account-status" id="account-status" role="status" aria-live="polite">Đang kiểm tra trạng thái đăng nhập…</p><section class="account-panel" id="account-login-panel" hidden><div class="account-login-copy"><h2>Đăng nhập tài khoản</h2><p>Dùng tài khoản Google đã xác minh để đồng bộ hồ sơ đã lưu.</p></div><div class="account-login-actions"><div id="account-turnstile" class="account-turnstile" aria-label="Xác minh chống spam"></div><button class="btn primary" id="account-google-signin" type="button" disabled>Đăng nhập bằng Google</button></div></section><div id="account-profile-panel" hidden><section class="account-panel account-identity"><div class="account-avatar" id="account-avatar" aria-hidden="true">•</div><div><span class="eyebrow">ĐÃ ĐĂNG NHẬP</span><h2 id="account-name"></h2><p id="account-email"></p><span class="account-role" id="account-role"></span></div><button class="btn" id="account-signout" type="button">Đăng xuất</button></section><section class="account-panel account-participation" aria-labelledby="account-participation-title"><div class="section-head"><div><span class="eyebrow">DẤU ẤN CỘNG ĐỒNG</span><h2 id="account-participation-title">Hoạt động của bạn</h2></div></div><div class="account-stat-grid"><div class="account-stat"><strong id="account-comment-count">0</strong><span>Bình luận đã đăng</span></div><div class="account-stat"><strong id="account-like-count">0</strong><span>Tim đã thả</span><small>Tính các lượt thích đang giữ</small></div><div class="account-stat account-rank-stat"><span>Cấp bậc bình luận</span><strong id="account-rank"></strong><p id="account-rank-progress"></p></div></div><p class="account-rank-guide">Thành viên mới: 0 · Thành viên: 1–99 · Fan cứng: 100–499 · Fan siêu cứng: từ 500 bình luận.</p></section><section class="account-saved-section"><div class="section-head"><div><span class="eyebrow">THƯ VIỆN CỦA BẠN</span><h2>Trang đã lưu</h2><p id="account-saved-description" hidden>Hồ sơ bách khoa và chương truyện bạn đã lưu được đồng bộ với tài khoản này.</p></div><span id="account-saved-count" class="account-saved-count"></span></div><div id="account-saved-list" class="account-saved-list" aria-live="polite"><p>Đang tải danh sách hồ sơ đã lưu…</p></div></section></div><p class="account-error" id="account-error" role="status" aria-live="polite"></p></div>`,{noindex:true});page('/gioi-thieu/','Về Mục Thần Ký','Khám phá phim hoạt hình, truyện, nhân vật và thế giới Mục Thần Ký trong một không gian dành cho người hâm mộ.',heading('Theo dấu Tần Mục. Khám phá Đại Khư.','Một hành trình nối phim, truyện và bách khoa Mục Thần Ký trong cùng một nơi.','VỀ MỤC THẦN KÝ')+`<div class="wrap prose about-page"><section class="about-opening"><span class="eyebrow">MỘT THẾ GIỚI · VẠN ĐIỀU KHÁM PHÁ</span><h2>Mở rộng câu chuyện sau mỗi khung hình</h2><p>Mucthanky.com được tạo nên cho những người muốn bước sâu hơn vào thế giới Mục Thần Ký. Từ hành trình của Tần Mục ở Tàn Lão Thôn đến những bí ẩn rộng lớn của Đại Khư, mỗi trang giúp bạn nối các chi tiết và khám phá câu chuyện theo cách riêng.</p></section><section><h2>Phim, truyện và bách khoa cùng một hành trình</h2><p>Website kết nối các nhánh phim hoạt hình và tiểu thuyết với hồ sơ nhân vật, cảnh giới, thần thông, công pháp, thế lực, địa danh và bảo vật. Bạn có thể bắt đầu từ một tập phim, một chương truyện hay một câu hỏi bất chợt rồi lần theo những mối liên hệ trong thế giới này.</p><div class="about-doors"><a class="btn" href="/phim/">Khám phá phim <span aria-hidden="true">↗</span></a><a class="btn" href="/truyen/">Đọc truyện <span aria-hidden="true">↗</span></a><a class="btn" href="/bach-khoa/">Tra cứu bách khoa <span aria-hidden="true">↗</span></a></div></section><section><h2>Hướng tới trải nghiệm xem phim ngay trên website</h2><p>Mục tiêu tiếp theo là đưa trải nghiệm xem phim đến trực tiếp trên mucthanky.com, để bạn có thể theo dõi các tập phim và mở ngay hồ sơ liên quan mà không đứt mạch khám phá. Trang phim sẽ tiếp tục được hoàn thiện để kết nối thông tin tập, lịch phát hành, nhân vật và những chi tiết đáng chú ý trong từng chặng truyện.</p></section><section><h2>Một bách khoa được mở rộng cùng cộng đồng</h2><p>Các hồ sơ được sắp xếp để dễ đọc trên máy tính lẫn điện thoại, có liên kết giữa các khái niệm và được bổ sung theo thời gian. Cộng đồng cũng là một phần của hành trình: người hâm mộ có thể cùng trao đổi, chia sẻ cách nhìn và giúp những chi tiết thú vị được nhiều người biết đến hơn.</p><div class="about-doors"><a class="btn primary" href="/cong-dong/">Ghé thăm cộng đồng <span aria-hidden="true">↗</span></a><a class="btn" href="/ung-ho/">Tiếp sức cho dự án <span aria-hidden="true">↗</span></a></div></section></div>`);
