fs.writeFileSync(`${out}/robots.txt`,'User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /quan-tri/\nDisallow: /nguyen-minh-duy/\nSitemap: https://mucthanky.com/sitemap.xml\n');
fs.writeFileSync(`${out}/_headers`,`/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src 'self'; script-src 'self' https://challenges.cloudflare.com 'unsafe-inline'; style-src 'self' https://fonts.googleapis.com 'unsafe-inline'; font-src 'self' https://fonts.gstatic.com; img-src 'self' https://i.ytimg.com data:; connect-src 'self' https://challenges.cloudflare.com; frame-src https://streamfree.vip https://www.youtube.com https://challenges.cloudflare.com https://player.bilibili.com https://www.facebook.com; object-src 'none'; base-uri 'self'; form-action 'self'\n  Cache-Control: no-cache, must-revalidate\n/assets/*\n  Cache-Control: public, max-age=86400\n/assets/style.css\n  Cache-Control: public, max-age=0, must-revalidate\n/assets/app.js\n  Cache-Control: public, max-age=0, must-revalidate\n/assets/episode-videos.json\n  Cache-Control: no-cache, must-revalidate\n/assets/admin.js\n  Cache-Control: public, max-age=0, must-revalidate\n`);
console.log(`Built ${routes.length} pages and ${entries.length} encyclopedia entries → dist`);

